"""Pin-focused differential fuzz."""
import json, random, sys
sys.path.insert(0, '/workspace/tmp')
import reference, fuzz
from fuzz_fast import run_engine

def make_session(rng):
    topo = reference.Topology(fuzz.random_topology(rng))
    ngroups = rng.randint(1, 3)
    ntasks = rng.randint(1, 6)
    groups = [[rng.randint(1, 3), rng.randint(1, 10)] for _ in range(ngroups)]
    domains = sorted(set(topo.domains))
    gd = [rng.choice(domains) for _ in range(ngroups)]
    gc = [rng.randint(0, 2) for _ in range(ngroups)]
    tasks = []
    for t in range(ntasks):
        g = rng.randrange(ngroups)
        cand = [i for i, d in enumerate(topo.domains) if d == gd[g]]
        tmpl = rng.choice(cand)
        tasks.append([tmpl, g, rng.randint(1, 6), gc[g], rng.choice([0, 1, 1, 1])])
    state = reference.State(topo, [0] * topo.n, groups, tasks)
    use = state.usage()
    caps = [u + rng.choice([0, 2]) for u in use]
    load = state.loads()
    for g in range(ngroups):
        if load[g]:
            need = (load[g] + groups[g][1] - 1) // groups[g][1]
            if need > groups[g][0]: groups[g][0] = min(64, need)
    session = {'topology': topo.spec, 'caps': caps, 'groups': groups, 'tasks': tasks,
               'query': {'groups': [], 'nodes': [], 'tasks': []}, 'transactions': []}
    revision = 0
    for _ in range(rng.randint(1, 6)):
        edits = []
        for _ in range(rng.randint(1, 5)):
            op = rng.choice(['weight', 'class', 'bind', 'move', 'pin', 'quota', 'quota', 'budget', 'cap'])
            if op in ('weight', 'class', 'bind', 'move', 'pin'):
                t = rng.randrange(ntasks)
                if op == 'weight':
                    # sometimes the same weight, sometimes different
                    w = tasks[t][2] if rng.random() < 0.3 else rng.randint(1, 12)
                    edits.append(['weight', t, w])
                elif op == 'class':
                    c = tasks[t][3] if rng.random() < 0.3 else rng.randint(0, 3)
                    edits.append(['class', t, c])
                elif op == 'bind':
                    tm = tasks[t][0] if rng.random() < 0.3 else rng.randrange(len(topo.pairs))
                    edits.append(['bind', t, tm])
                elif op == 'move':
                    gg = tasks[t][1] if rng.random() < 0.3 else rng.randrange(ngroups)
                    edits.append(['move', t, gg])
                else:
                    edits.append(['pin', t, rng.choice([0, 1])])
            elif op == 'quota':
                g = rng.randrange(ngroups)
                q = groups[g][0] if rng.random() < 0.3 else rng.randint(0, 5)
                edits.append(['quota', g, q])
            elif op == 'budget':
                g = rng.randrange(ngroups)
                edits.append(['budget', g, rng.randint(1, 15)])
            else:
                edits.append(['cap', rng.randrange(topo.n), rng.randint(0, 30)])
        q = {'groups': [rng.randrange(ngroups) for _ in range(rng.randint(0, 2))],
             'nodes': [rng.randrange(topo.n) for _ in range(rng.randint(0, 2))],
             'tasks': [rng.randrange(ntasks) for _ in range(rng.randint(0, 2))]}
        session['transactions'].append({'revision': revision, 'edits': edits, 'query': q})
        revision += 1
    return session

def main():
    seed0 = int(sys.argv[1]); rounds = int(sys.argv[2])
    bad = 0
    for r in range(rounds):
        rng = random.Random(seed0 + r)
        request = {'version': 2, 'sessions': [make_session(rng) for _ in range(rng.randint(1, 2))]}
        try:
            expected = reference.run(request)
        except ValueError:
            expected = {'error': 'invalid'}
        actual = run_engine(request)
        if json.dumps(actual, sort_keys=True) != json.dumps(expected, sort_keys=True):
            bad += 1
            print('seed', seed0 + r, 'MISMATCH')
            open('/workspace/tmp/failpins-%d.json' % (seed0 + r), 'w').write(json.dumps(request))
            for i, (a, e) in enumerate(zip(actual.get('sessions', []), expected.get('sessions', []))):
                if json.dumps(a, sort_keys=True) != json.dumps(e, sort_keys=True):
                    ta = a['transactions']; te = e['transactions']
                    for j, (x, y) in enumerate(zip(ta, te)):
                        if json.dumps(x, sort_keys=True) != json.dumps(y, sort_keys=True):
                            print('  tx', j, 'actual', json.dumps(x)[:900]); print('  tx', j, 'expect', json.dumps(y)[:900])
                            break
                    break
            if bad >= 3: break
    print('rounds', rounds, 'mismatches', bad)
    return 1 if bad else 0

if __name__ == '__main__':
    raise SystemExit(main())
